const $ = selector => document.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state = { health:{}, user:null, workspaces:[], ws:null, jobs:[], view:'overview', connection:'salesforce', jobId:null, jobTab:'requirements', file:null, demo:false, modal:null, busy:false, events:[] };
const services={salesforce:['SF','Salesforce','Development org'],jira:['J','Jira','Project and issue mapping'],github:['G','GitHub CI/CD','Repository and environment pipeline'],llm:['AI','Development LLM','Provider and model']};
const stages={intake:'BRD intake',clarification:'Needs clarification',plan_review:'Plan review',approved:'Plan approved',code_review:'Code review',validating:'Validating',validated:'Validation passed',deploying:'Deploying',sandbox_deployed:'Acceptance review',sandbox_complete:'Development complete',failed:'Needs attention'};
const sampleBrd=`Service Request Priority\n\nCreate a Service_Request__c custom object with Subject, Priority, Status, and Due Date. Priority choices are Low, Medium, and High. Status choices are New, In Progress, and Closed.\n\nHigh priority requests should be due within two business days. Standard users can create requests and update their own requests. Supervisors can view and update all requests.\n\nA supervisor dashboard must show open requests by priority. Existing records must not be deleted.\n\nAcceptance: Users can create requests, unauthorized users cannot access them, and supervisors can see a count of open requests by priority.`;
const samplePlan={summary:'A governed service request workspace with clear ownership, priority, and supervisor visibility.',solution:'Use a custom Service Request object, permission sets, a record-triggered Flow for due dates, and a report/dashboard. Confirm the business calendar and sharing rules before implementation.',requirements:[{id:'REQ-1',title:'Capture a service request',source:'Create a Service_Request__c custom object with Subject, Priority, Status, and Due Date.',acceptance:['A user can create a request with subject, priority, and status.','Priority and status accept only the agreed choices.']},{id:'REQ-2',title:'Apply a priority-based due date',source:'High priority requests should be due within two business days.',acceptance:['A High priority request receives a due date two business days after creation.','Holiday and weekend behavior follows the approved business calendar.']},{id:'REQ-3',title:'Protect records and show supervisor reporting',source:'Standard users can create requests and update their own requests. Supervisors can view and update all requests.',acceptance:['Standard users cannot update requests owned by someone else.','A supervisor can view and update all requests.','Supervisors can report on open requests by priority.']}],questions:[{id:'Q-1',question:'Which business hours, timezone, and holiday calendar define “two business days”?',reason:'The due-date rule needs an unambiguous calendar.',blocking:true},{id:'Q-2',question:'Should standard users be able to view other users’ requests, or only their own?',reason:'Update rules do not fully define record visibility.',blocking:true}],stories:[{id:'STORY-1',title:'Create service request data model',description:'Build the request object and required fields.',requirements:['REQ-1'],acceptance:['The request object supports the approved fields and choices.']},{id:'STORY-2',title:'Automate priority due dates',description:'Add a Flow or Apex implementation after calendar clarification.',requirements:['REQ-2'],acceptance:['Due dates match approved business-calendar scenarios.']},{id:'STORY-3',title:'Configure access and supervisor reporting',description:'Add permission sets, sharing, and a report/dashboard.',requirements:['REQ-3'],acceptance:['Visibility and edit access match the approved roles.']}],risks:['The current org must be inspected for an existing service request solution.','Due-date behavior is blocked until the business calendar is confirmed.'],testPlan:['Create a request as a standard user.','Attempt unauthorized cross-owner updates.','Create High priority requests on weekends and holidays.','Verify supervisor reporting totals.']};

function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',7000);}
async function api(op,body,params={}){
  const query=new URLSearchParams({op,...params});
  const response=await fetch('/api/service?'+query,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{})});
  const result=await response.json();if(!response.ok)throw new Error(result.error || 'The request failed.');return result;
}
async function refresh(){
  if(state.demo){render();return;}
  const info=await api('status');state.user=info.user;state.workspaces=info.workspaces;
  state.ws=info.workspaces.find(w=>w.id===state.ws?.id)||info.workspaces[0]||null;
  if(state.ws)state.jobs=(await api('jobs',null,{workspaceId:state.ws.id})).jobs;else state.jobs=[];
  render();
}
const currentJob=()=>state.jobs.find(j=>j.id===state.jobId);
const conn=type=>state.ws?.connections.find(c=>c.type===type);
const roleCanWrite=()=>['owner','developer'].includes(state.ws?.role);
const roleCanReview=()=>['owner','reviewer'].includes(state.ws?.role);
const button=(label,action,classes='',disabled=false,extra='')=>`<button type="button" class="${classes}" data-act="${action}" ${disabled?'disabled':''} ${extra}>${label}</button>`;
function pill(text,variant=''){return `<span class="pill ${variant}">${esc(text)}</span>`;}
function statusPill(stage){return pill(stages[stage]||stage,stage==='sandbox_complete'||stage==='validated'?'':stage==='clarification'||stage==='plan_review'||stage==='code_review'?'amber':'grey');}
function connectionRows(){return Object.entries(services).map(([type,[icon,name]])=>{
  const c=conn(type),detail=c?.config?.orgName||c?.config?.projectKey||c?.config?.repo||c?.config?.pipelineName||c?.config?.model||'Add connection';
  const label=c?type==='copado'?'Manual handoff':c.verified?'Verified':'Configured':'Not configured';
  return `<div class="connection-row"><div class="service-icon">${icon}</div><div class="service-detail">${name}<small>${esc(detail)}</small></div>${pill(label,c?.verified?'':'grey')}</div>`;
}).join('');}
function render(){
  $('#app').innerHTML=!state.user?login():shell();
  if(state.modal)renderModal();
  const provider=$('[name="provider"]');if(provider){const azure=provider.value==='azure';const ep=$('[name="endpoint"]');ep.required=azure;ep.disabled=state.demo||!azure||state.ws?.role!=='owner';$('[name="apiVersion"]').disabled=state.demo||!azure||state.ws?.role!=='owner';}
  if(state.busy)document.body.insertAdjacentHTML('beforeend','<div class="loading-strip"></div>');
}
function login(){return `<main class="login"><section class="login-art"><div class="brand"><img src="/icon.svg" alt=""><span>Delivery Studio<small>Salesforce development</small></span></div><div><div class="eyebrow">From requirement to release</div><h1>Business intent.<br>Working Salesforce.</h1><p>A shared workspace for turning your BRD into development work, with your tools, your accounts, and human review at every release gate.</p><div class="login-list"><span>01 / Clarify</span><span>02 / Build</span><span>03 / Validate</span><span>04 / Review</span></div></div><small>Jira · GitHub Actions · Salesforce MCP · Your LLM</small></section><section class="login-form"><div><div class="eyebrow">Your delivery workspace</div><h2>Welcome to the studio.</h2><p class="muted">Sign in to connect your team’s tools and begin with a business requirements document.</p>${state.health.unavailable?'<div class="banner error">The app could not reach its server. Retry the page or check the deployment API logs.</div>':''}${!state.health.configured?'<div class="banner">Server setup is required for live connections. You can explore the interface using the sample workspace below.</div>':''}${state.health.missingSettings?.length?`<details class="note"><summary>Server settings still needed</summary><ul>${state.health.missingSettings.map(k=>`<li><code>${esc(k)}</code></li>`).join('')}</ul><p>Add these in Vercel environment variables, then redeploy. Create test users in Supabase Auth after installing the database schema.</p></details>`:''}<form data-form="login"><div class="field"><label for="email">Work email</label><input id="email" name="email" type="email" autocomplete="username" required ${!state.health.configured?'disabled':''}></div><div class="field"><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="current-password" minlength="8" required ${!state.health.configured?'disabled':''}></div><button class="primary" type="submit" ${!state.health.configured?'disabled':''}>Sign in →</button>${state.health.signupEnabled?button('Create an account','signup','subtle'):''}</form><div class="divider">EXPLORE FIRST</div>${button('Open sample workspace','demo')}<small>Live data stays within your workspace. Model calls occur only when you request analysis or code generation. Production runs only through the protected GitHub Actions pipeline.</small></div></section></main>`;}
function shell(){
  const nav=[['overview','◈','Overview'],['deliveries','▤','Deliveries'],['approvals','✓','Reviews'],['connections','⇄','Connections'],['audit','◷','Activity']];
  return `<div class="shell"><aside class="sidebar"><div class="brand"><img src="/icon.svg" alt=""><span>Delivery Studio<small>Salesforce development</small></span></div><div class="workspace-picker"><label for="workspace" class="eyebrow">Workspace</label><select id="workspace"><option value="">${state.ws?'Select workspace':'Create your first workspace'}</option>${state.workspaces.map(w=>`<option value="${esc(w.id)}" ${state.ws?.id===w.id?'selected':''}>${esc(w.name)}</option>`).join('')}</select>${button('+ New workspace','newWorkspace','subtle')}</div><nav class="nav" aria-label="Main navigation">${nav.map(([v,i,n])=>button(`<span class="nav-icon">${i}</span>${n}${v==='deliveries'?`<span class="count">${state.jobs.length}</span>`:''}`,'navigate',state.view===v||state.view==='job'&&v==='deliveries'?'active':'',false,`data-view="${v}"`)).join('')}</nav><div class="sidebar-bottom"><div class="environment"><span class="dot"></span><strong>Development delivery pilot</strong><br><span class="muted">Production requires a protected pipeline and human approval.</span></div><div class="user-row"><span class="avatar">${esc(state.user.email[0]?.toUpperCase())}</span><span>${esc(state.user.email)}<br>${esc(state.ws?.role||'No workspace')}</span></div>${state.demo?selectField('Test identity','demoRole',[['owner','Test owner'],['developer','Test developer'],['reviewer','Test reviewer'],['viewer','Test viewer']],state.ws.role,false):''}${button(state.demo?'Exit sample':'Sign out','logout','subtle')}</div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Workspace <span>/</span><strong>${esc(state.ws?.name||'Get started')}</strong></div>${pill(state.demo?'SAMPLE WORKSPACE':'DEVELOPMENT ONLY',state.demo?'amber':'')}</header><div class="content">${state.demo?'<div class="banner">Sample workspace · Actions preview the workflow using sample data. No credentials, model calls, tickets, commits, tests, or deployments are performed.</div>':''}${!state.ws?noWorkspace():({overview,deliveries,connections,approvals,audit:activity,job:jobView}[state.view]||overview)()}<div class="footer-note"><span>Delivery Studio / v0.4.0 · Development pilot</span><span>Requirements → Stories → Changes → Test evidence → Human approval</span></div></div></main></div>`;
}
function heading(kicker,title,description,action=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="muted">${description}</p></div>${action}</div>`;}
function noWorkspace(){return heading('Getting started','Make room for your next release.','Create a workspace to keep your accounts, requirements, and delivery decisions together.')+`<div class="card empty"><div class="empty-symbol">+</div><h3>Your team’s own configuration</h3><p>Each workspace has separate Salesforce, Jira, GitHub CI/CD, and model settings.</p>${button('Create workspace','newWorkspace','primary')}</div>`;}
function overview(){
  const pending=state.jobs.filter(j=>['clarification','plan_review','code_review','validated','sandbox_deployed'].includes(j.stage));
  return heading('Delivery overview','A clear path from BRD to build.','Plan the work, resolve the unknowns, and ship a reviewed change to your development org.',button('+ New delivery','newDelivery','primary',!roleCanWrite()))+`<div class="grid two"><section class="hero"><div class="eyebrow">Begin with the business need</div><h2>Your next feature starts<br>with a better question.</h2><p>Bring a requirements document. The studio identifies what to build, asks what’s missing, and prepares a traceable delivery plan.</p>${button('Start a delivery →','newDelivery','',!roleCanWrite())}</section><section class="card"><div class="card-heading"><h3>Your connected tools</h3>${button('Manage','navigate','subtle',false,'data-view="connections"')}</div>${connectionRows()}</section></div><div class="stats"><div class="stat"><div class="eyebrow">Deliveries</div><div class="stat-number">${String(state.jobs.length).padStart(2,'0')}</div><small>Requirements in the workspace</small></div><div class="stat"><div class="eyebrow">Needs your input</div><div class="stat-number">${String(pending.length).padStart(2,'0')}</div><small>Questions or review decisions</small></div><div class="stat"><div class="eyebrow">Development complete</div><div class="stat-number">${String(state.jobs.filter(j=>j.stage==='sandbox_complete').length).padStart(2,'0')}</div><small>Verified deployment results</small></div></div><div class="grid two"><section class="card"><div class="card-heading"><h3>Recent deliveries</h3>${button('View all','navigate','subtle',false,'data-view="deliveries"')}</div>${jobTable(state.jobs.slice(0,4))}</section><section class="card"><div class="card-heading"><h3>The delivery checkpoints</h3>${pill('HUMAN REVIEW')}</div>${[['Understand','Extract requirements and resolve blocking questions.'],['Design & build','Approve the plan, then review generated metadata.'],['Validate & deliver','Test the exact package and approve a development deployment.']].map(([title,detail],i)=>`<div class="flow-row"><span class="step-number">0${i+1}</span><div><strong>${title}</strong><p>${detail}</p></div></div>`).join('')}</section></div>`;
}
function jobTable(jobs){return jobs.length?`<div class="table-wrap"><table><thead><tr><th>Delivery</th><th>Stage</th><th></th></tr></thead><tbody>${jobs.map(j=>`<tr><td class="title-cell">${esc(j.title)}<small>${esc(j.id.slice(0,8))} · ${new Date(j.created_at).toLocaleDateString()}</small></td><td>${statusPill(j.stage)} ${j.data.paused?pill('Paused','red'):''}</td><td>${button('Open →','openJob','',false,`data-id="${esc(j.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><div class="empty-symbol">▤</div><h3>No deliveries yet</h3><p>Add your first BRD to create a requirement-led development plan.</p>${button('New delivery','newDelivery','primary',!roleCanWrite())}</div>`;}
function deliveries(){return heading('Delivery workspace','Every requirement, accounted for.','Open a delivery to inspect its questions, work items, metadata, and test evidence.',button('+ New delivery','newDelivery','primary',!roleCanWrite()))+`<section class="card">${jobTable(state.jobs)}</section>`;}
function setupChecklist(){const checks=state.ws.readiness||Object.keys(services).map(type=>({type,ready:false,message:'Add connection'}));return `<p class="muted">${checks.filter(c=>c.ready).length} / 4 configured or verified</p>${checks.map(c=>`<div class="section-spacer">${button(`${c.ready?'✓':'○'} ${services[c.type][1]}`,'connection','subtle',false,`data-type="${c.type}"`)}<small>${esc(c.message)}</small></div>`).join('')}`;}
function capabilityView(c){const r=c.capabilities;return `<section class="card section-spacer"><h3>License & capability evidence</h3>${r?`<p><strong>${esc(r.edition)}</strong> · ${esc(r.environment)}</p><small>Checked ${esc(r.checkedAt)}</small><p>${esc(r.evidence.connectedUser.value?.license||'Connected user license: unknown')}</p>${Object.entries(r.evidence).map(([key,e])=>`<details><summary>${esc(key)} — ${esc(e.status)}</summary><pre class="wrap">${esc(JSON.stringify(e.value||e.reason,null,2))}</pre></details>`).join('')}<ul>${r.guidance.map(g=>`<li>${esc(g)}</li>`).join('')}</ul><p>${esc(r.deployment)}</p>`:'<p>Authorize Salesforce to inspect available license and permission evidence.</p>'}${button('Refresh license & capability report','refreshCapabilities','',!roleCanWrite()||state.demo)}</section>`;}
function connections(){const type=state.connection,c=conn(type)?.config||{},owner=state.ws.role==='owner';return heading('Workspace setup','Your tools. Your development org.','Configure each connection for this workspace. Credentials are encrypted on the server and never returned to the browser.')+`<div class="tabs" role="group" aria-label="Connections">${Object.entries(services).map(([t,[,name]])=>button(name,'connection',t===type?'active':'',false,`data-type="${t}"`)).join('')}</div><div class="grid two"><section class="card"><div class="card-heading"><h2>${services[type][1]} connection</h2>${pill(conn(type)?.verified?'Verified':conn(type)?'Configured':'Not configured',conn(type)?.verified?'':'grey')}</div>${!owner?'<div class="banner">Only workspace owners can change connection settings.</div>':''}${state.demo?'<div class="banner">Connection editing is disabled in the sample. Sign in to use your own accounts.</div>':''}<form data-form="connection" data-type="${type}">${connectionFields(type,c,(!owner||state.demo))}${type==='llm'?'<div class="note">Test model connection sends one small synthetic request to your model provider and may incur API usage charges. No BRD or org data is sent.</div>':''}<div class="actions section-spacer"><button class="primary" type="submit" ${!owner||state.demo?'disabled':''}>Save connection</button>${button(type==='salesforce'?'Authorize Salesforce →':type==='llm'?'Test model connection':'Check connection','verify','',!conn(type)||!owner||state.demo,`data-type="${type}"`)}</div></form>${type==='salesforce'?capabilityView(c):''}<div class="note">Saving new settings invalidates outstanding approvals. Enter the credential again when editing a connection. Existing deliveries retain their account binding and must be recreated after configuration changes.</div></section><aside><section class="card"><h3>Setup checklist</h3>${setupChecklist()}${connectionRows()}<div class="note">Select the Salesforce source repository with the reviewed delivery workflow installed. Environment credentials remain in GitHub environment secrets.</div></section><section class="card section-spacer"><h3>Team access</h3><p class="muted">Add an existing user by their account ID. Reviewers approve releases; developers build them; viewers inspect progress.</p>${button('Manage team access','members','',!owner||state.demo)}</section></aside></div>`;}
function field(label,name,value='',hint='',type='text',disabled=false,placeholder=''){const id='field-'+name;return `<div class="field"><label for="${id}">${label}</label><input id="${id}" name="${name}" value="${esc(value)}" type="${type}" ${disabled?'disabled':''} placeholder="${esc(placeholder)}" required ${type==='password'?'autocomplete="new-password"':''}>${hint?`<small>${hint}</small>`:''}</div>`;}
function selectField(label,name,options,value,disabled){return `<div class="field"><label for="field-${name}">${label}</label><select id="field-${name}" name="${name}" ${disabled?'disabled':''}>${options.map(([v,l])=>`<option value="${v}" ${v===value?'selected':''}>${l}</option>`).join('')}</select></div>`;}
function connectionFields(type,c,d){
  if(type==='salesforce')return selectField('Development environment','environment',[['sandbox','Sandbox'],['developer','Developer Edition']],c.environment||'sandbox',d)+`<div class="field"><label for="field-expectedOrgId">Expected organization ID</label><input id="field-expectedOrgId" name="expectedOrgId" value="${esc(c.expectedOrgId||'')}" ${d?'disabled':''} pattern="00D[A-Za-z0-9]{12}([A-Za-z0-9]{3})?"><small>Required for Developer Edition. Copy Organization ID from Salesforce Setup → Company Information. Production orgs are blocked.</small></div>`+field('Development org URL','url',c.url,'Use the My Domain login URL for the selected environment. The server verifies the org type and ID.','url',d,'https://yourcompany--dev.sandbox.my.salesforce.com')+field('External Client App client ID','clientId',c.clientId,'Create an External Client App with Web Server OAuth flow and api / refresh_token scopes.','text',d)+field('Client secret','clientSecret','','Encrypted at rest. Never include this in Git.','password',d)+`<div class="note">OAuth callback URL<br><span class="mono">${esc(location.origin)}/api/service?op=sfCallback</span></div>`;
  if(type==='jira')return field('Jira Cloud URL','url',c.url,'Jira Server/Data Center is not supported in this pilot.','url',d,'https://yourteam.atlassian.net')+`<div class="form-grid">${field('Project key','projectKey',c.projectKey,'Example: CRM','text',d)}${field('Issue type ID','issueTypeId',c.issueTypeId,'Use a Story or Task issue type available in your project.','text',d)}</div><div class="section-spacer">${field('Atlassian account email','email',c.email,'','email',d)}${field('API token','token','','Use an API token with access to this project.','password',d)}</div><div class="field"><label for="jira-defaults">Jira field defaults (JSON)</label><textarea id="jira-defaults" name="fieldDefaults" rows="5" ${d?'disabled':''}>${esc(JSON.stringify(c.fieldDefaults||{},null,2))}</textarea><small>Optional defaults for required fields, for example {&quot;customfield_10001&quot;:{&quot;id&quot;:&quot;10002&quot;}}. Check connection identifies missing fields. Project, issue type, summary, description and tracking labels are managed automatically.</small></div>`;
  if(type==='github')return field('Salesforce repository URL','url',c.url,'Use a private Salesforce source repository. Install the reviewed runner and workflow on its protected branch.','url',d,'https://github.com/team/salesforce')+`<div class="form-grid">${field('Base branch','branch',c.branch||'main','New changes go to an isolated sfda/<delivery-id> branch.','text',d)}${field('Salesforce source directory','sourcePath',c.sourcePath||'force-app/main/default','Source-format package directory.','text',d)}</div><div class="section-spacer">${field('Fine-grained access token','token','','Limit the token to this repository and grant Contents read/write. Pull requests are reviewed through your existing process.','password',d)}</div>`+`<div class="field"><label for="pipeline-config">CI/CD configuration (JSON)</label><textarea id="pipeline-config" name="pipeline" rows="12" ${d?'disabled':''}>${esc(JSON.stringify(c.pipeline||{enabled:false},null,2))}</textarea><small>Enable after installing the trusted runner and configuring four distinct orgs. See docs/PIPELINE.md for the complete template, credentials and approval rules.</small></div>`;
  if(type==='copado')return selectField('Which Copado pipeline do you use?','pipelineType',[['unknown','Not sure — identify during setup'],['metadata','Salesforce Metadata Pipelines'],['source','Salesforce Source Format Pipelines'],['essentials','Copado Essentials']],c.pipelineType||'unknown',d)+field('Pipeline name','pipelineName',c.pipelineName,'','text',d)+`<div class="form-grid">${field('Development environment','devEnvironment',c.devEnvironment,'','text',d)}${field('UAT environment','uatEnvironment',c.uatEnvironment,'','text',d)}</div><div class="section-spacer">${field('Release owner','releaseOwner',c.releaseOwner,'','text',d)}</div><div class="banner">Manual Copado handoff is supported. Automatic Copado promotion and production deployment are disabled until your edition-specific connector is implemented and verified.</div>`;
  return selectField('Approved model provider','provider',[['openai','OpenAI API'],['azure','Azure OpenAI']],c.provider||'openai',d)+field('Model / Azure deployment name','model',c.model,'Choose a model that supports Chat Completions with JSON mode. The application does not assume a model name.','text',d)+`<div id="azure-fields">${field('Azure endpoint (Azure only)','endpoint',c.endpoint||'','Use https://RESOURCE.openai.azure.com. Leave blank for OpenAI.','url',d)}${field('Azure API version','apiVersion',c.apiVersion||'2024-10-21','Confirm the supported API version for your deployment.','text',d)}</div>`+field('API key','token','','Your BRD, answers, approved plan, and selected org metadata are sent to this provider when you request generation.','password',d);
}
function approvals(){const jobs=state.jobs.filter(j=>['clarification','plan_review','code_review','validated','sandbox_deployed'].includes(j.stage));return heading('Human checkpoints','Keep judgment in the loop.','Inspect the evidence, answer the questions, and approve the exact change being delivered.')+`<section class="card">${jobTable(jobs)}</section><div class="banner green section-spacer">Approvals record the reviewer, artifact hash, account configuration, and time. A changed artifact invalidates its code and deployment approvals. The server enforces these gates.</div>`;}
function activity(){return heading('Workspace activity','A record of what changed.','Connection updates, development steps, and approval decisions are recorded with the acting user.')+`<section class="card"><div class="card-heading"><h3>Latest activity</h3>${button('Refresh','loadAudit','')}</div>${state.events.length?`<div class="table-wrap"><table><thead><tr><th>Event</th><th>Actor</th><th>Time</th></tr></thead><tbody>${state.events.map(e=>`<tr><td><strong>${esc(e.action)}</strong><small class="mono preformatted"> ${esc(JSON.stringify(e.details))}</small></td><td>${esc(e.actor_email)}</td><td>${esc(new Date(e.created_at).toLocaleString())}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><p>No events loaded. Refresh to retrieve the latest workspace activity.</p></div>'}</section>`;}
function releaseChecklist(j){return `<section class="card tight section-spacer"><h3>Sandbox prechecks</h3>${(j.releaseChecks||[]).map(c=>`<p>${c.pass?'✓':'○'} ${esc(c.name)}</p>`).join('') || '<p class="muted">Prechecks appear after the next refresh.</p>'}<small>Approval expires after four hours. The server checks the current Git branch before deployment.</small></section>`;}
function jobView(){const j=currentJob();if(!j)return deliveries();const d=j.data;const idx=['intake','clarification','plan_review'].includes(j.stage)?0:j.stage==='approved'?1:j.stage==='code_review'?2:['validating','validated','sandbox_deployed'].includes(j.stage)?3:4;return heading('Delivery / '+esc(j.id.slice(0,8)),esc(j.title),'Review the requirement, its implementation, and the evidence before taking the next step.',`<div class="actions">${button('← Deliveries','navigate','subtle',false,'data-view="deliveries"')}${button(d.paused?'Resume':'Pause for review',d.paused?'resume':'pause','',!roleCanWrite()&&!roleCanReview())}</div>`)+`${d.lastError?`<div class="banner error">${esc(d.lastError)}</div>`:''}${d.paused?'<div class="banner">Delivery paused. No further development actions can run. A Salesforce deployment already submitted may continue in the org; check its status separately.</div>':''}${j.busy||d.reconciliationRequired?`<div class="banner">An operation needs reconciliation. Confirm its outcome in the external system before unlocking.${button('Record reconciliation','reconcile','subtle',!roleCanReview())}</div>`:''}<div class="stepper">${['Understand','Approve plan','Build & review','Validate','Development release'].map((s,i)=>`<div class="stage ${i===idx?'current':i<idx?'done':''}">0${i+1} / ${s}</div>`).join('')}</div><div class="job-layout"><section><div class="tabs">${[['requirements','Requirements'],['stories','Work items'],['files','Changes'],['tests','Test evidence'],['architecture','Architecture'],['mockup','Mockup'],['pipeline','CI/CD']].map(([t,l])=>button(l,'jobTab',state.jobTab===t?'active':'',false,`data-tab="${t}"`)).join('')}</div>${jobContent(j)}</section><aside>${jobControls(j)}${releaseChecklist(j)}<section class="card tight"><div class="eyebrow">Release identity</div>${statusPill(j.stage)}<p class="mono section-spacer">${esc(d.orgContext?.org.name||'Org not yet inspected')}</p><small>Artifact SHA-256</small><p class="mono wrap">${esc(d.artifacts?.hash||'No generated release')}</p><small>Deployment: GitHub Actions + Salesforce MCP<br>Production requires human approval</small>${button('Download release bundle','download','section-spacer',!d.artifacts)}</section></aside></div>`;}
function jobContent(j){if(state.jobTab==='architecture')return architectureView(j);if(state.jobTab==='mockup')return mockupView(j);if(state.jobTab==='pipeline')return pipelineView(j);const d=j.data,p=d.plan;
  if(state.jobTab==='requirements')return `<section class="card">${!p?`<h2>The business requirement</h2><p class="preformatted">${esc(d.brd)}</p><div class="note">Analyze the BRD to extract requirements and identify follow-up questions. The configured LLM receives this document and selected org metadata.</div>`:`<div class="eyebrow">Solution outline</div><h2>${esc(p.summary)}</h2><p class="preformatted muted">${esc(p.solution)}</p>${p.questions.length?`<div class="section-spacer"><h3>Clarification questions</h3><form data-form="answers">${p.questions.map(q=>`<div class="field"><label for="answer-${q.id}">${esc(q.question)} ${pill(q.blocking?'Blocking':'Optional',q.blocking?'amber':'grey')}</label><small>${esc(q.reason)}</small><textarea id="answer-${q.id}" name="${esc(q.question)}" rows="3" ${q.blocking?'required':''}>${esc(d.answers?.[q.question]||'')}</textarea></div>`).join('')}<button type="submit" class="primary" ${!['clarification','plan_review'].includes(j.stage)||!roleCanWrite()?'disabled':''}>Submit answers & reanalyze</button></form></div>`:''}<h3 class="section-spacer">Traceable requirements</h3>${p.requirements.map(r=>`<article class="requirement"><div class="eyebrow">${r.id}</div><h3>${esc(r.title)}</h3><blockquote>${esc(r.source)}</blockquote><ul>${r.acceptance.map(a=>`<li>${esc(a)}</li>`).join('')}</ul></article>`).join('')}${p.risks.length?`<div class="note"><strong>Risks & constraints</strong><ul>${p.risks.map(r=>`<li>${esc(r)}</li>`).join('')}</ul></div>`:''}${button('Review / edit plan JSON','editPlan','',j.stage!=='plan_review'||!roleCanWrite())}`}</section>`;
  if(state.jobTab==='stories')return `<section class="card"><div class="card-heading"><h2>Development work items</h2>${pill(`${Object.keys(d.jira||{}).length} / ${p?.stories.length||0} in Jira`,'grey')}</div>${!p?'<p class="muted">Analyze the BRD to prepare stories.</p>':p.stories.map(s=>`<article class="story"><div class="actions">${pill(s.id,'grey')}${s.requirements.map(r=>pill(r,'grey')).join('')}${d.jira?.[s.id]?`<a href="${esc(d.jira[s.id].url)}" target="_blank" rel="noopener noreferrer">${esc(d.jira[s.id].key)} ↗</a>`:''}</div><h3>${esc(s.title)}</h3><p class="muted">${esc(s.description)}</p><ul>${s.acceptance.map(a=>`<li>${esc(a)}</li>`).join('')}</ul></article>`).join('')}${button('Create next Jira work item','jira','primary',!p||!['approved','code_review','validated','sandbox_deployed'].includes(j.stage)||!roleCanWrite()||p?.stories.every(s=>d.jira?.[s.id]))}<div class="note">One story is created per action. After an ambiguous response, reconcile the project before retrying to avoid duplicate work.</div></section>`;
  if(state.jobTab==='files'){
    if(!d.artifacts)return `<section class="card empty"><div class="empty-symbol">⌘</div><h3>No generated changes yet</h3><p>Approve the plan before requesting code generation.</p></section>`;
    const file=d.artifacts.files.find(f=>f.path===state.file)||d.artifacts.files[0];state.file=file.path;
    return `<section class="card"><h2>Review the generated release</h2><div class="note">${esc(d.artifacts.notes)}</div><div class="file-list">${d.artifacts.files.map(f=>button(esc(f.path),'file',f.path===file.path?'active':'',false,`data-path="${esc(f.path)}"`)).join('')}</div><label for="code">${esc(file.path)}</label><textarea id="code" class="code-editor" spellcheck="false" ${j.stage!=='code_review'||!roleCanWrite()||file.path==='package.xml'?'readonly':''}>${esc(file.content)}</textarea><div class="actions section-spacer">${button('Save reviewed file','saveFile','',j.stage!=='code_review'||!roleCanWrite()||file.path==='package.xml')}${button('Commit to isolated Git branch','git','primary',!d.approvals?.code||d.git?.hash===d.artifacts.hash||!['code_review','validated','sandbox_deployed'].includes(j.stage)||!roleCanWrite())}${d.git?`<a href="${esc(d.git.url)}" target="_blank" rel="noopener noreferrer">Open ${esc(d.git.branch)} ↗</a>`:''}</div><small class="section-spacer">package.xml is generated by the server. Saving a file resets code approval. Metadata API files are converted to source format when committed to Git. Review object decomposition and existing source conventions before merging.</small></section>`;
  }
  return testSuiteView(j)+`<section class="card"><h2>Test evidence, not assumptions.</h2><div class="note">Validation uses a Salesforce check-only deployment with RunLocalTests. Business acceptance, UI, and external integration scenarios still require review in your development org.</div>${p?.testPlan?.length?`<h3>Acceptance scenarios</h3><ul class="checklist">${p.testPlan.map(t=>`<li><span>○</span>${esc(t)} <small>Manual verification required</small></li>`).join('')}</ul>`:''}${['validation','deployment'].map(type=>{const run=d[type];return `<div class="section-spacer"><h3>${type==='validation'?'Package validation':'Development deployment'}</h3>${!run?'<p class="muted">Not run</p>':`${pill(run.result?.status||'Submitted',run.result?.success?'':'grey')}<p class="mono section-spacer">ID: ${esc(run.id)}</p><p>Tests run: ${run.result?.testsRun??'Pending'} · Test errors: ${run.result?.testErrors??'Pending'}</p>${run.result?.messages?.length?`<div class="banner error">${run.result.messages.map(m=>`<p>${esc(m.name)}: ${esc(m.problem)}</p>`).join('')}</div>`:''}`}</div>`;}).join('')}${j.stage==='sandbox_deployed'?`<form data-form="acceptance" class="section-spacer"><h3>Record acceptance evidence</h3>${p.testPlan.map((t,i)=>`<div class="field"><label for="evidence-${i}">${esc(t)}</label><textarea id="evidence-${i}" name="${i}" required minlength="10" rows="2" placeholder="Observed result, test user, and evidence reference…"></textarea></div>`).join('')}<button class="primary" type="submit" ${!roleCanReview()?'disabled':''}>Confirm acceptance & complete</button></form>`:''}${d.acceptance?`<div class="banner green section-spacer">Acceptance recorded for ${d.acceptance.length} scenarios.</div>`:''}<div class="actions section-spacer">${button('Validate package & run tests','validate','primary',j.stage!=='code_review'||!d.approvals?.code||!roleCanWrite())}${button('Refresh Salesforce status','poll','',!['validating','deploying'].includes(j.stage))}</div></section>`;
}
function jobControls(j){const d=j.data,blocked=d.paused||j.busy;return `<section class="review-box"><div class="eyebrow">Next checkpoint</div><h3>${stages[j.stage]}</h3>${j.stage==='intake'?`<p>Analyze the BRD using your configured model and current development org metadata.</p>${button('Analyze with development LLM','analyze','primary',blocked||!roleCanWrite())}`:j.stage==='clarification'?'<p>Answer the blocking questions, then reanalyze. The plan cannot be approved until those questions are resolved.</p>':j.stage==='plan_review'?`<p>Confirm the requirements, proposed solution, and acceptance criteria.</p>${button('Approve development plan','approvePlan','primary',blocked||!roleCanReview())}`:j.stage==='approved'?`<p>Create linked Jira stories and generate the implementation for code review.</p>${button(d.mockup?'Regenerate mockup':'Generate concept mockup','mockup','',blocked||!roleCanWrite())}${button('Approve mockup','approveMockup','',blocked||!roleCanReview()||!d.mockup||!!d.mockupApproval)}${button('Generate Salesforce changes','generate','primary',blocked||!roleCanWrite()||!d.mockupApproval)}`:j.stage==='code_review'?`<p>Review every generated file and its risks. Approval applies to this exact artifact.</p>${button(d.approvals?.code?'Code approved':'Approve reviewed code','approveCode','primary',blocked||!roleCanReview()||!!d.approvals?.code)}`:j.stage==='validated'?`<p>Validation passed. Review the test results, ensure Jira work and Git commits exist, and authorize this development release.</p>${button(d.approvals?.sandbox?'Development release approved':'Approve development release','approveDeploy','primary',blocked||!roleCanReview()||!!d.approvals?.sandbox)}${button('Deploy to development org','deploy','',blocked||!roleCanWrite()||!d.approvals?.sandbox)}`:j.stage==='sandbox_deployed'?'<p>Deployment succeeded. Run the acceptance scenarios in the development org and record evidence in the Test evidence tab to complete the delivery.</p>':j.stage==='sandbox_complete'?'<p>The Salesforce deployment completed successfully. Verify business behavior, then use the protected CI/CD pipeline for subsequent environments.</p>':`<p>Salesforce is processing the submitted package. Refresh its status to retrieve the actual result.</p>${button('Refresh operation status','poll','primary')}`}</section>`;}
function renderModal(){const m=state.modal;let content='';
  if(m==='workspace')content=`<h2>Create a workspace</h2><form data-form="workspace">${field('Workspace name','name','','','text',false,'CRM development')}<div class="actions">${button('Cancel','closeModal')}<button type="submit" class="primary">Create workspace</button></div></form>`;
  if(m==='delivery')content=`<h2>Start with the business need</h2><p class="muted section-spacer">Paste your BRD or load a plain text / Markdown file. PDF and Word conversion are not included in this pilot.</p><form data-form="delivery">${field('Delivery title','title','','','text',false,'Service Request Priority')}<div class="field"><label for="brdFile">Load a document (.txt or .md)</label><input id="brdFile" type="file" accept=".txt,.md,text/plain,text/markdown"></div><div class="field"><label for="brd">Business requirements</label><textarea id="brd" name="brd" required minlength="30" maxlength="80000" rows="10" placeholder="Business objective, rules, roles, acceptance criteria, and constraints…"></textarea></div><small>Creating a delivery saves the BRD in your workspace. Analysis sends it to your configured model provider only when you request it.</small><div class="actions">${button('Cancel','closeModal')}<button class="primary" type="submit">Create delivery</button></div></form>`;
  if(m==='plan')content=`<h2>Review the plan JSON</h2><form data-form="plan"><div class="field"><label for="plan">Requirements, stories, questions, and test scenarios</label><textarea id="plan" name="plan" class="code-editor" rows="18">${esc(JSON.stringify(currentJob().data.plan,null,2))}</textarea></div><div class="actions">${button('Cancel','closeModal')}<button class="primary" type="submit">Save revised plan</button></div></form>`;
  if(m==='members')content=`<h2>Assign a team role</h2><p class="muted section-spacer">Ask the teammate for the account ID shown in their workspace status. An administrator can also find it in Supabase Auth.</p><p class="mono">Your account ID: ${esc(state.user.id)}</p><form data-form="member">${field('Existing user account ID','userId')}${selectField('Workspace role','role',[['developer','Developer — build and test'],['reviewer','Reviewer — approve and resume'],['viewer','Viewer — inspect only']],'developer',false)}<div class="actions">${button('Cancel','closeModal')}<button class="primary" type="submit">Assign role</button></div></form>`;
  if(m==='reconcile')content=`<h2>Record human reconciliation</h2><p class="muted section-spacer">Check Jira, GitHub, and the Salesforce deployment monitor. Recovery is available after the ten-minute operation lease expires. Recorded outcomes are preserved and the delivery stays paused. Writes with unknown outcomes remain blocked and require administrator investigation.</p><form data-form="reconcile"><label for="note">What happened, and what is safe to do next?</label><textarea id="note" name="note" required minlength="20" rows="5"></textarea><div class="actions">${button('Cancel','closeModal')}<button class="primary" type="submit">Record findings</button></div></form>`;
  $('#app').insertAdjacentHTML('beforeend',`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(m)}">${content}</section></div>`);
  $('.modal input:not([disabled]),.modal textarea')?.focus();
}
function demo(){state.demo=true;state.user={id:'sample-owner',email:'owner@example.test'};state.ws={id:'sample-workspace',name:'CRM Development',role:'owner',connection_version:0,connections:[]};state.workspaces=[state.ws];state.jobs=[{id:'sample-delivery-001',workspace_id:state.ws.id,title:'Service Request Priority',stage:'clarification',created_at:new Date().toISOString(),data:{brd:sampleBrd,plan:structuredClone(samplePlan),answers:{},connectionVersion:0,paused:false}}];state.view='overview';state.jobId=null;state.modal=null;state.events=[];render();}
async function action(op,extra={}){
  if(state.demo){return demoAction(op,extra);}
  let result;
  try{result=await api(op,{workspaceId:state.ws.id,jobId:state.jobId,...extra});}catch(error){try{await refresh();}catch{}throw error;}
  if(result.job){const i=state.jobs.findIndex(j=>j.id===result.job.id);if(i<0)state.jobs.unshift(result.job);else state.jobs[i]=result.job;}
  render();toast('Action completed.');
}
function demoAction(op,extra){
  const j=currentJob();if(!j)throw new Error('Open the sample delivery first.');
  const allowed=op==='pause'?['owner','developer','reviewer']:['approvePlan','resume'].includes(op)?['owner','reviewer']:['owner','developer'];
  if(!allowed.includes(state.ws.role))throw new Error('This test identity cannot perform that action.');
  if(j.data.paused && op!=='resume')throw new Error('Delivery is paused for human intervention.');
  if(op==='pause'||op==='resume'){j.data.paused=op==='pause';}
  else if(op==='analyze'){
    if(!['intake','clarification','plan_review'].includes(j.stage))throw new Error('The approved delivery cannot be reanalyzed.');
    if(j.data.brd!==sampleBrd)throw new Error('Sample analysis supports the included Service Request BRD only. Sign in with a configured model to analyze your own document.');
    j.data.plan=structuredClone(samplePlan);j.data.answers=extra.answers||j.data.answers||{};
    for(const q of j.data.plan.questions)q.blocking=!j.data.answers[q.question]?.trim();
    j.stage=j.data.plan.questions.some(q=>q.blocking)?'clarification':'plan_review';
  }else if(op==='approvePlan'){
    if(j.stage!=='plan_review'||j.data.plan.questions.some(q=>q.blocking))throw new Error('Resolve blocking questions before approval.');
    j.stage='approved';
  }else throw new Error('This action needs live connections. Exit the sample and sign in to your configured server.');
  state.events.unshift({action:'sample.'+op,actor_email:state.user.email,created_at:new Date().toISOString(),details:{sample:true,jobId:j.id}});
  render();toast('Sample action recorded. No model call or external change was made.');
}
async function doClick(el){const act=el.dataset.act;
  if(act==='demo')return demo();
  if(act==='logout'){if(!state.demo)await api('logout',{});Object.assign(state,{demo:false,user:null,ws:null,workspaces:[],jobs:[],events:[],modal:null,view:'overview'});return render();}
  if(act==='navigate'){state.view=el.dataset.view;state.modal=null;render();if(state.view==='audit')await loadAudit();return;}
  if(act==='newWorkspace'){if(state.demo)return toast('The sample has one workspace. Sign in to create your own.');state.modal='workspace';return render();}
  if(act==='newDelivery'){if(!roleCanWrite())throw new Error('This role cannot create deliveries.');state.modal='delivery';return render();}
  if(act==='closeModal'){state.modal=null;return render();}
  if(act==='connection'){state.connection=el.dataset.type;render();const endpoint=$('[name="endpoint"]');if(endpoint&&state.connection==='llm')endpoint.required=$('[name="provider"]').value==='azure';return;}
  if(act==='openJob'){state.jobId=el.dataset.id;state.view='job';state.jobTab='requirements';state.file=null;return render();}
  if(act==='jobTab'){state.jobTab=el.dataset.tab;return render();}
  if(act==='file'){state.file=el.dataset.path;return render();}
  if(act==='editPlan'){state.modal='plan';return render();}
  if(act==='members'){state.modal='members';return render();}
  if(act==='reconcile'){state.modal='reconcile';return render();}
  if(act==='refreshCapabilities'){await api('verifyConnection',{workspaceId:state.ws.id,type:'salesforce'});toast('Capability evidence refreshed');return refresh();}
  if(act==='verify'){
    const type=el.dataset.type;
    if(type==='salesforce'){const result=await api('authorizeSalesforce',{workspaceId:state.ws.id});location.assign(result.url);return;}
    const result=await api('verifyConnection',{workspaceId:state.ws.id,type});toast(result.details.message||`Verified: ${result.details.name}`);return refresh();
  }
  if(act==='download'){if(state.demo)throw new Error('Generate a live release before downloading the release bundle.');location.assign('/api/service?'+new URLSearchParams({op:'download',workspaceId:state.ws.id,jobId:state.jobId}));return;}
  if(act==='approveBusiness'){const note=prompt('Record your business approval rationale after reviewing the complete release report:');if(!note)return;await api('approveBusiness',{workspaceId:state.ws.id,jobId:state.jobId,note});return refresh();}
  if(act==='refreshPipeline')return refresh();
  if(act==='loadAudit')return loadAudit();
  if(act==='signup'){const form=el.closest('form'),data=Object.fromEntries(new FormData(form));const r=await api('signup',data);if(r.confirmationRequired)toast('Check your email to confirm your account, then sign in.');else await refresh();return;}
  if(act==='saveFile'){const j=currentJob(),files=j.data.artifacts.files.map(f=>({...f,content:f.path===state.file?$('#code').value:f.content}));return action('editArtifacts',{files});}
  return action(act);
}
async function loadAudit(){state.events=state.demo?state.events:(await api('audit',null,{workspaceId:state.ws.id})).events;render();}
async function doSubmit(form){const data=Object.fromEntries(new FormData(form));const kind=form.dataset.form;
  if(kind==='mockupRevision')return action('mockup',{feedback:data.feedback});
  if(kind==='manualTest')return action('manualEvidence',data);
  if(kind==='acceptance')return action('acceptance',{evidence:Object.keys(data).sort((a,b)=>Number(a)-Number(b)).map(k=>data[k])});
  if(kind==='login'){const r=await api('login',data);if(r.confirmationRequired)return toast('Confirm your email before signing in.');return refresh();}
  if(kind==='workspace'){const result=await api('createWorkspace',data);state.ws={id:result.id};state.modal=null;await refresh();state.view='connections';return render();}
  if(kind==='connection'){if(data.provider==='openai'){delete data.endpoint;delete data.apiVersion;}await api('saveConnection',{workspaceId:state.ws.id,type:form.dataset.type,config:data});toast('Connection saved. Outstanding approvals were invalidated.');return refresh();}
  if(kind==='delivery'){
    if(!roleCanWrite())throw new Error('This role cannot create deliveries.');
    let job;if(state.demo)job={id:crypto.randomUUID(),title:data.title,stage:'intake',created_at:new Date().toISOString(),data:{brd:data.brd,connectionVersion:0}};
    else job=(await api('createJob',{workspaceId:state.ws.id,...data})).job;
    state.jobs.unshift(job);state.jobId=job.id;state.modal=null;state.view='job';state.jobTab='requirements';return render();
  }
  if(kind==='answers'){const old=currentJob().data.answers||{};const answers={...old,...Object.fromEntries(Object.entries(data).filter(([,v])=>v.trim()))};return action('analyze',{answers});}
  if(kind==='plan'){const plan=JSON.parse(data.plan);state.modal=null;return action('editPlan',{plan});}
  if(kind==='member'){await api('addMember',{workspaceId:state.ws.id,...data});state.modal=null;render();return toast('Workspace role assigned.');}
  if(kind==='reconcile'){state.modal=null;return action('reconcile',{note:data.note});}
}
async function perform(callback){if(state.busy)return;state.busy=true;document.body.insertAdjacentHTML('beforeend','<div class="loading-strip"></div>');try{await callback();}catch(e){toast(e.message,true);}finally{state.busy=false;document.querySelectorAll('.loading-strip').forEach(e=>e.remove());}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(el&&!el.disabled)perform(()=>doClick(el));});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(form){e.preventDefault();perform(()=>doSubmit(form));}});
document.addEventListener('change',e=>{
  if(e.target.name==='demoRole'&&state.demo){const role=e.target.value;if(!['owner','developer','reviewer','viewer'].includes(role))return;state.ws.role=role;state.user={id:'sample-'+role,email:role+'@example.test'};state.modal=null;render();return;}
  if(e.target.id==='workspace')perform(async()=>{state.ws=state.workspaces.find(w=>w.id===e.target.value)||state.ws;state.view='overview';await refresh();});
  if(e.target.name==='provider'){const endpoint=$('[name="endpoint"]');if(endpoint){endpoint.required=e.target.value==='azure';endpoint.disabled=e.target.value!=='azure';$('[name="apiVersion"]').disabled=e.target.value!=='azure';}}
  if(e.target.id==='brdFile')perform(async()=>{const f=e.target.files[0];if(!f)return;if(f.size>100000||!/^.*\.(txt|md)$/i.test(f.name))throw new Error('Choose a .txt or .md document smaller than 100 KB.');const text=await f.text();if(text.length>80000)throw new Error('BRDs are limited to 80,000 characters.');$('#brd').value=text;});
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal){state.modal=null;render();}if(e.key==='Tab'&&state.modal){const controls=[...document.querySelectorAll('.modal button:not(:disabled),.modal input:not(:disabled),.modal textarea,.modal select')];const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
(async()=>{try{state.health=await api('health');if(state.health.configured)await refresh();else render();}catch(e){if(!state.health.configured)state.health.unavailable=true;render();if(state.health.configured&&e.message!=='Sign in to continue.')toast(e.message,true);}})();

function mockupView(j){const d=j.data;return `<section class="card"><h2>Review the experience before building</h2><p>AI-generated concept screens. These are proposals, not evidence of a deployed Salesforce feature.</p>${!d.mockup?'<p>No mockup generated yet. Approve the plan first.</p>':`<p>${esc(d.mockup.notes)}</p><div class="mockup-grid">${d.mockup.screens.map(s=>`<article class="mockup-screen"><div class="mockup-chrome">SALESFORCE · CONCEPT</div><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><small>${s.requirements.map(esc).join(' · ')}</small>${s.fields.map(f=>`<div class="field"><label>${esc(f.label)}</label><div class="mockup-value">${esc(f.example)}</div></div>`).join('')}<div class="actions">${s.actions.map(a=>`<span class="pill">${esc(a)}</span>`).join('')}</div></article>`).join('')}</div>`}<div class="actions section-spacer">${button('Generate mockup','mockup','primary',j.stage!=='approved'||!roleCanWrite())}${button(d.mockupApproval?'Mockup approved':'Approve mockup','approveMockup','',j.stage!=='approved'||!d.mockup||!!d.mockupApproval||!roleCanReview())}</div>${j.stage==='approved'&&roleCanWrite()?`<form data-form="mockupRevision" class="section-spacer"><label for="mockup-feedback">Request an AI revision</label><textarea id="mockup-feedback" name="feedback" required maxlength="4000" rows="3" placeholder="Describe what should change within the approved requirements"></textarea><button type="submit">Revise mockup</button></form>`:''}<small>${d.mockupHistory?.length||0} previous revisions retained. Revision invalidates mockup approval.</small></section>`;}
function testSuiteView(j){const d=j.data;return `<section class="card"><h2>Requirement-linked test scripts</h2><p>AI proposes the tests; the runner records actual results. Review the expectations before running. Missing evidence blocks promotion.</p><div class="actions">${button('Generate test scripts','generateTests','',j.stage!=='code_review'||!roleCanWrite())}${button(d.testApproval?'Tests approved':'Approve test suite','approveTests','',!d.testSuite||j.stage!=='code_review'||!roleCanReview())}</div>${(d.testSuite?.scenarios||[]).map(s=>`<article class="story"><h3>${esc(s.id)} · ${esc(s.title)}</h3>${pill(s.kind,'grey')}<small>${s.requirements.map(esc).join(' · ')}</small><p>${esc(s.expected)}</p><pre class="wrap">${esc(JSON.stringify(s.kind==='browser'?s.steps:s.apexClasses,null,2))}</pre>${s.kind==='manual'&&roleCanReview()?`<form data-form="manualTest"><input type="hidden" name="testId" value="${esc(s.id)}"><label>Observed result and evidence reference</label><textarea name="note" required minlength="20" rows="2">${esc(d.manualEvidence?.[s.id]?.note||'')}</textarea><button type="submit">Record reviewed evidence</button></form>`:''}</article>`).join('')}</section>`;}
function pipelineView(j){const p=j.data.pipeline;return `<section class="card"><h2>Dev → QA → UAT → Business approval → Production</h2><p>The configured stage order is enforced on the server. UAT and production require protected GitHub environment reviews. Automatic fixes return to the first stage; production failures require human investigation.</p><div class="actions">${button('Start reviewed pipeline','startPipeline','primary',!roleCanWrite()||!j.data.testApproval||!j.data.approvals?.code||!!p&&!['failed','complete','stopped'].includes(p.status))}${button('Refresh pipeline status','refreshPipeline')}${p?.runUrl?`<a href="${esc(p.runUrl)}" target="_blank" rel="noopener noreferrer">Open run and approvals ↗</a>`:''}</div>${j.data.releaseReport?`<details class="section-spacer"><summary>Business approval report — requirements, Jira, components and test evidence</summary><pre class="wrap">${esc(JSON.stringify(j.data.releaseReport,null,2))}</pre></details>${button('Approve business release','approveBusiness','primary',!roleCanReview()||p?.status!=='awaiting_business_approval'||!!j.data.businessApproval)}`:''}${p?`<p>Status: <strong>${esc(p.status)}</strong> · Repair attempts: ${p.repairs} / ${p.policy.maxRepairs}</p><p class="mono wrap">Release ${esc(p.artifactHash)}</p>${p.policy.stages.map(s=>{const r=p.stages.find(r=>r.name===s.name);return `<article class="story"><h3>${esc(s.name)} · ${esc(r?.status||'Waiting')}</h3><small>${esc(s.environment)} · ${esc(s.orgId)}</small><p>${esc(r?.reason||'Awaiting prior stages, environment approval, or runner setup.')}</p>${r?.validation?`<p>Validation: ${esc(r.validation.status)} · ${r.validation.testsRun||0} Apex tests</p>`:''}${(r?.tests||[]).map(t=>`<p>${esc(t.id)}: ${t.passed?'Passed':'Failed'}</p>`).join('')}</article>`;}).join('')}`:'<p>No pipeline started. Configure GitHub CI/CD, approve the mockup and test suite, create Jira stories, and commit the reviewed implementation.</p>'}</section>`;}

function architectureView(j){const a=j.data.architecture;return `<section class="card"><h2>Salesforce architecture</h2><p>Review metadata evidence, component designs, permissions, license constraints and deployment risks before code generation.</p>${button('Generate architecture','architecture','primary',j.stage!=='approved'||!roleCanWrite())}${button('Approve architecture','approveArchitecture','',!a||a.unresolved.length>0||j.stage!=='approved'||!roleCanReview())}${a?`<pre class="wrap">${esc(JSON.stringify(a,null,2))}</pre>`:'<p>No architecture generated.</p>'}</section>`;}
